package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class ScoreBoardTest {

    @Test
    fun ranksTopThreeByScoreDescTieByName() {
        val csv = "name,score\nalice,50\nbob,90\ncarol,70\ndave,90\n"
        // 90: bob,dave (name asc); then carol 70 -> top three
        assertEquals(listOf("bob" to 90, "dave" to 90, "carol" to 70), ScoreBoard.topThree(csv))
    }

    @Test
    fun skipsInvalidRows() {
        val csv = "name,score\nalice,50\n,99,\nbob,notanumber\ncarol,70\n"
        assertEquals(listOf("carol" to 70, "alice" to 50), ScoreBoard.topThree(csv))
    }

    @Test
    fun fewerThanThreeReturnsAll() {
        assertEquals(listOf("x" to 10), ScoreBoard.topThree("name,score\nx,10\n"))
    }

    @Test
    fun headerOnlyIsEmpty() {
        assertEquals(emptyList<Pair<String, Int>>(), ScoreBoard.topThree("name,score\n"))
    }

    @Test
    fun integratesWithPrinter() {
        val csv = "name,score\nalice,50\nbob,90\ncarol,70\n"
        assertEquals("bob: 90\ncarol: 70\nalice: 50", LeaderboardPrinter.render(csv))
    }
}

