package com.optarena.app

object ScoreBoard {
    // BUG: only skips non-integer scores, not blank names, so a blank-name
    // row with a high score wrongly ranks.
    fun topThree(csv: String): List<Pair<String, Int>> {
        val lines = csv.trim().lines()
        if (lines.size <= 1) return emptyList()
        return lines.drop(1)
            .mapNotNull { line ->
                if (line.isBlank()) return@mapNotNull null
                val cols = line.split(",")
                val name = cols.getOrNull(0)?.trim().orEmpty()
                val score = cols.getOrNull(1)?.trim()?.toIntOrNull()
                if (score == null) null else name to score
            }
            .sortedWith(compareByDescending<Pair<String, Int>> { it.second }.thenBy { it.first })
            .take(3)
    }
}
